import { Suspense } from "react";
import { createClient } from "@/lib/supabase/server";
import { PostComments, type CommentView } from "./comments/post-comments";

async function Account() {
  const supabase = await createClient();
  const { data } = await supabase.auth.getUser();
  return data.user ? <p>Signed in as {data.user.email}</p> : <p><a href="/login">Sign in</a></p>;
}

async function Posts() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  const { data: posts, error } = await supabase
    .from("posts")
    .select("id, title, body, created_at, profiles(display_name)")
    .order("created_at", { ascending: false });

  if (error) {
    return <p>Could not load posts: {error.message}</p>;
  }

  // One query for every visible post's comments, grouped by post below.
  const postIds = posts?.map((post) => post.id) ?? [];
  const { data: commentRows, error: commentsError } = postIds.length
    ? await supabase
        .from("comments")
        .select("id, post_id, body, created_at, author_id, profiles(display_name)")
        .in("post_id", postIds)
        .order("created_at", { ascending: true })
    : { data: [], error: null };

  if (commentsError) {
    return <p>Could not load comments: {commentsError.message}</p>;
  }

  const commentsByPost = new Map<number, CommentView[]>();
  for (const row of (commentRows ?? []) as unknown as Array<{
    id: number;
    post_id: number;
    body: string;
    created_at: string;
    author_id: string;
    profiles: { display_name: string } | null;
  }>) {
    const list = commentsByPost.get(row.post_id) ?? [];
    list.push({
      id: row.id,
      body: row.body,
      created_at: row.created_at,
      author_id: row.author_id,
      author_name: row.profiles?.display_name ?? "Unknown",
    });
    commentsByPost.set(row.post_id, list);
  }

  return (
    <>
      {posts?.map((post) => (
        <article key={post.id} style={{ margin: "24px 0" }}>
          <h2>{post.title}</h2>
          <small>
            {(post.profiles as unknown as { display_name: string } | null)?.display_name ?? "Unknown"} ·{" "}
            {new Date(post.created_at).toLocaleDateString("en-GB")}
          </small>
          <p>{post.body}</p>
          <PostComments
            postId={post.id}
            comments={commentsByPost.get(post.id) ?? []}
            currentUserId={user?.id ?? null}
          />
        </article>
      ))}
    </>
  );
}

